<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import FinanceScenarioBar from '../components/FinanceScenarioBar.vue'
import FinanceSubnav from '../components/FinanceSubnav.vue'
import { useFinanceStore } from '../runtime/finance-store'
import type { FinanceRole } from '../types'
import type { FinanceScenarioName } from '../../../../mock/handlers/finance-handler'
import './finance-views.css'
import './finance-receivable-views.css'

const props = defineProps<{ mode: 'customers' | 'documents' | 'products' | 'aging' }>()
const store = useFinanceStore(); const route = useRoute(); const router = useRouter()
const { customerReceivables, receivableDocuments, receivableProducts, agingRows, loading, error, scenario, actor } = storeToRefs(store)
const keyword = ref(String(route.query.keyword ?? '')); const startDate = ref(String(route.query.startDate ?? '')); const endDate = ref(String(route.query.endDate ?? ''))
const money = (value: number) => `¥${(value / 100).toLocaleString('zh-CN', { minimumFractionDigits: 2 })}`
const date = (value: string | null) => value ? value.slice(0, 10) : '—'
const statusLabel = { open: '待收', partial: '部分收款', settled: '已收' } as const
const title = computed(() => ({ customers: '客户应收', documents: '应收明细（按单据）', products: '应收明细（按商品）', aging: '应收账龄' })[props.mode])
const totals = computed(() => customerReceivables.value.reduce((sum, item) => ({ receivable: sum.receivable + item.receivableCents, received: sum.received + item.receivedCents, outstanding: sum.outstanding + item.outstandingCents }), { receivable: 0, received: 0, outstanding: 0 }))
async function search() { await router.replace({ query: { ...(keyword.value ? { keyword: keyword.value } : {}), ...(startDate.value ? { startDate: startDate.value } : {}), ...(endDate.value ? { endDate: endDate.value } : {}) } }); await store.loadReceivables({ keyword: keyword.value, startDate: startDate.value || undefined, endDate: endDate.value || undefined }) }
async function reset() { keyword.value = ''; startDate.value = ''; endDate.value = ''; await search() }
async function changeScenario(value: FinanceScenarioName) { await store.setScenario(value); await search() }
async function changeRole(value: FinanceRole) { await store.setRole(value); await search() }
onMounted(search)
</script>

<template><section class="finance-page"><header class="finance-header"><div><h1>{{ title }}</h1><p>应收由订单确认发货形成，已收与待收只根据有效核销计算。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="changeScenario" @role="changeRole"/></header><FinanceSubnav/><div class="finance-tabs"><RouterLink to="/finance/receivables">按客户</RouterLink><RouterLink to="/finance/receivables/documents">按单据</RouterLink><RouterLink to="/finance/receivables/products">按商品</RouterLink><RouterLink to="/finance/receivables/aging">账龄</RouterLink></div><div v-if="mode!=='aging'" class="finance-toolbar"><div class="finance-filter-row"><label>关键字<input v-model="keyword" placeholder="客户名称/编码/订单号"></label><label>形成日期从<input v-model="startDate" type="date"></label><label>形成日期至<input v-model="endDate" type="date"></label></div><div><button class="fin-button" @click="reset">清空</button><button class="fin-button primary" @click="search">查询</button></div></div><div class="finance-summary"><article><span>应收金额</span><strong>{{money(totals.receivable)}}</strong></article><article><span>已收金额</span><strong class="fin-income">{{money(totals.received)}}</strong></article><article><span>待收金额</span><strong class="fin-expense">{{money(totals.outstanding)}}</strong></article><article><span>有效应收单</span><strong>{{receivableDocuments.length}}</strong></article></div><div v-if="error" class="finance-state error" role="alert"><strong>应收数据加载失败</strong><p>{{error}}</p><button class="fin-button" @click="search">重试</button></div><div v-else-if="loading" class="finance-state"><strong>正在加载应收数据…</strong></div><div v-else-if="mode==='customers'" class="finance-table-wrap"><table class="finance-table"><thead><tr><th>客户名称</th><th class="fin-money">应收金额</th><th class="fin-money">已收金额</th><th class="fin-money">待收金额</th><th>最后收款日期</th><th class="fin-money">账期天数</th><th>操作</th></tr></thead><tbody><tr v-for="row in customerReceivables" :key="row.customer.id"><td><strong>{{row.customer.name}}</strong><small>{{row.customer.code}}</small></td><td class="fin-money">{{money(row.receivableCents)}}</td><td class="fin-money fin-income">{{money(row.receivedCents)}}</td><td class="fin-money fin-expense"><strong>{{money(row.outstandingCents)}}</strong></td><td>{{date(row.lastReceiptDate)}}</td><td class="fin-money">{{row.oldestAgeDays}} 天</td><td><RouterLink :to="`/finance/receivables/documents?keyword=${row.customer.code}`">查看明细</RouterLink> <RouterLink v-if="row.outstandingCents>0 && actor.role!=='sales-supervisor'" :to="`/finance/writeoffs/new?customerId=${row.customer.id}`">核销</RouterLink></td></tr><tr v-if="!customerReceivables.length"><td colspan="7">暂无客户应收</td></tr></tbody></table></div><div v-else-if="mode==='documents'" class="finance-table-wrap"><table class="finance-table wide-table"><thead><tr><th>单据日期/应收号</th><th>订单号</th><th>往来单位</th><th>联系人/电话</th><th class="fin-money">订货金额</th><th class="fin-money">运费</th><th class="fin-money">应收</th><th class="fin-money">已收</th><th class="fin-money">待收</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in receivableDocuments" :key="row.id"><td>{{date(row.occurredAt)}}<small>{{row.receivableNo}}</small></td><td><RouterLink :to="`/orders/${row.orderId}`">{{row.orderNo}}</RouterLink></td><td>{{row.customerSnapshot.name}}</td><td>{{row.customerSnapshot.contactName}}<small>{{row.customerSnapshot.phone}}</small></td><td class="fin-money">{{money(row.goodsAmountCents)}}</td><td class="fin-money">{{money(row.freightCents)}}</td><td class="fin-money">{{money(row.amountCents)}}</td><td class="fin-money fin-income">{{money(row.receivedCents)}}</td><td class="fin-money fin-expense">{{money(row.outstandingCents)}}</td><td><span class="fin-status" :class="row.status">{{statusLabel[row.status]}}</span><small v-if="row.overdue">已逾期</small></td><td><RouterLink v-if="row.outstandingCents>0 && actor.role!=='sales-supervisor'" :to="`/finance/receipts/new?customerId=${row.customerSnapshot.id}&orderId=${row.orderId}`">收款</RouterLink></td></tr><tr v-if="!receivableDocuments.length"><td colspan="11">暂无单据应收</td></tr></tbody></table></div><div v-else-if="mode==='products'" class="finance-table-wrap"><table class="finance-table"><thead><tr><th>日期/单号</th><th>客户</th><th>SKU</th><th>商品/规格</th><th class="fin-money">数量</th><th class="fin-money">单价</th><th class="fin-money">金额</th><th>应收状态</th></tr></thead><tbody><tr v-for="row in receivableProducts" :key="`${row.receivableId}-${row.orderLineId}`"><td>{{date(row.occurredAt)}}<small>{{row.orderNo}}</small></td><td>{{row.customer.name}}</td><td>{{row.skuCode}}</td><td>{{row.productName}}<small>{{row.specification}}</small></td><td class="fin-money">{{row.quantityMilli/1000}} {{row.unitName}}</td><td class="fin-money">{{money(row.unitPriceCents)}}</td><td class="fin-money">{{money(row.subtotalCents)}}</td><td><span class="fin-status" :class="row.status">{{statusLabel[row.status]}}</span></td></tr><tr v-if="!receivableProducts.length"><td colspan="8">暂无商品应收</td></tr></tbody></table></div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>客户</th><th class="fin-money">待收总额</th><th class="fin-money">0～30天</th><th class="fin-money">31～60天</th><th class="fin-money">61～90天</th><th class="fin-money">91～180天</th><th class="fin-money">181～365天</th><th class="fin-money">365天以上</th></tr></thead><tbody><tr v-for="row in agingRows" :key="row.customer.id"><td><strong>{{row.customer.name}}</strong><small>{{row.customer.code}}</small></td><td class="fin-money fin-expense"><strong>{{money(row.outstandingCents)}}</strong></td><td class="fin-money">{{money(row.bucket0To30Cents)}}</td><td class="fin-money">{{money(row.bucket31To60Cents)}}</td><td class="fin-money">{{money(row.bucket61To90Cents)}}</td><td class="fin-money">{{money(row.bucket91To180Cents)}}</td><td class="fin-money">{{money(row.bucket181To365Cents)}}</td><td class="fin-money">{{money(row.bucketOver365Cents)}}</td></tr><tr v-if="!agingRows.length"><td colspan="8">暂无待收账龄</td></tr></tbody></table></div></section></template>
